def count(table: str, id_column: str, id_value: str) -> int:
    conn = connect()
    try:
        cur = conn.execute(
            f"SELECT COUNT(*) FROM {_phys(table)} WHERE {id_column} = ?", (id_value,)
        )
        return int(cur.fetchone()[0])
    finally:
        conn.close()


